const fsSync=require('node:fs'),temp=fsSync.mkdtempSync(require('node:path').join(require('node:os').tmpdir(),'bluu-player-ci-')),source=JSON.parse(fsSync.readFileSync('.github/launcher-src/source.json','utf8'));for(const [name,data] of Object.entries(source))fsSync.writeFileSync(require('node:path').join(temp,name),data);
const test=require('node:test'),assert=require('node:assert/strict'),{lookupPlayer}=require(require('node:path').join(temp,'player-directory.cjs'));const uuid='1'.repeat(32),name='SluzzBeh';
function fixture(url='http://textures.minecraft.net/texture/a'){const png=Buffer.alloc(24);Buffer.from([137,80,78,71,13,10,26,10]).copy(png);png.writeUInt32BE(64,16);png.writeUInt32BE(64,20);const calls=[];return {calls,fetch:async(u,o)=>{calls.push(u);assert.equal(o.redirect,'error');if(u.includes('/users/profiles/'))return {ok:true,json:async()=>({id:uuid,name})};if(u.includes('/session/minecraft/'))return {ok:true,json:async()=>({id:uuid,name,properties:[{name:'textures',value:Buffer.from(JSON.stringify({textures:{SKIN:{url}}})).toString('base64')}]})};return {ok:true,arrayBuffer:async()=>png};}};}
test('exact official account lookup returns stable UUID and unflattened skin PNG for head rendering',async()=>{const f=fixture(),p=await lookupPlayer(name,f.fetch);assert.equal(p.uuid,uuid);assert.equal(p.name,name);assert.match(p.skin,/^data:image\/png;base64,/);assert(f.calls.includes('https://textures.minecraft.net/texture/a'));});
test('UUID lookup preserves identity and refuses unsafe texture hosts without fetching them',async()=>{const f=fixture('https://evil.test/texture');const p=await lookupPlayer(uuid,f.fetch);assert.equal(p.uuid,uuid);assert.equal(p.skin,null);assert(!f.calls.some(u=>u.includes('evil.test')));});
test('invalid names, unknown accounts and mismatched session identities cannot create a selected account',async()=>{await assert.rejects(lookupPlayer('../evil'));await assert.rejects(lookupPlayer('Missing',async()=>({ok:false})));await assert.rejects(lookupPlayer(uuid,async()=>({ok:true,json:async()=>({id:'2'.repeat(32),name})})));});

test.after(()=>fsSync.rmSync(temp,{recursive:true,force:true}));
